      "version": "2026.11-v1",
      "body": "Фиксированный принцип удерживает ось: в Огне это центр самовыражения, в Земле питающая ценность, в Воздухе связность принципа, в Воде глубина привязанности. Постоянство теряет назначение, когда требует остановить саму жизнь. Возможная развилка — беречь основание либо непрерывно доказывать, что его прежняя форма не должна измениться."
