      "incompatible_with": [],
      "version": "2026.11-v1",
      "body": "Фиксированный крест соотносится с серединой сезона и удержанием сформировавшегося качества. Его символическая задача — сохранить центр, позволяя жизни менять способы выражения этого постоянства.",
      "modality_id": "fixed"
